Lemma window_nth : forall (l xs : list byte) (base : Z) (k c : nat) (i : Z),
  firstn k (skipn (Z.to_nat base) l) = xs -> (0 <= base)%Z -> (c < k)%nat -> i = base + Z.of_nat c ->
  nth_error l (Z.to_nat i) = nth_error xs c.
