Definition strncpy_bytes (n : Z) (buf : list byte) : list byte :=
  firstn (Z.to_nat (strnlen_res n buf)) buf
  ++ repeat (Z_to_bv 8 0) (Z.to_nat (n - strnlen_res n buf)).

